def link_weaned_rabbits(apps, schema_editor):
    """Rattache à leur portée les fiches créées lors des sevrages précédents
    (même mère, même père et même date de naissance que la portée)."""
    Litter = apps.get_model('farm', 'Litter')
    Rabbit = apps.get_model('farm', 'Rabbit')
    for litter in Litter.objects.filter(is_deleted=False, weaned_count__gt=0):
        kits = Rabbit.objects.filter(
            owner_id=litter.owner_id, dam_id=litter.mother_id, sire_id=litter.father_id,
            birth_date=litter.birth_date, litter__isnull=True,
        ).order_by('id')[:litter.weaned_count]
        Rabbit.objects.filter(pk__in=[k.pk for k in kits]).update(litter=litter)


